  3	/// The `av1_webm` row's pipeline (spec §11 CX-15): the composed movie read back exactly as
  4	/// `ExportWriter` reads it, its picture encoded by the same `ExportEncodePump` and its sound
  5	/// by `ExportOpusEncoder`, written into a WebM by the core (`ReelWebM`).
  6	///
  7	/// **A second `ExportPipeline`, and the exception to §7.8's one writer (CX-15 (2)).**
  8	/// `AVAssetWriter` writes no WebM, so this file is the WebM half of `ExportWriter` and
  9	/// nothing more: the same reader outputs (`ExportWriter.videoReadOutput` /
 10	/// `audioReadOutput`), the same gain (`ExportAudioGain`), the same end of the sound
 11	/// (`ExportAudioEnd`, #337), the same chapters (`ExportChapter.partition`), the same size and
 12	/// rates (`encodedSize`, the pump). What is its own is the container: the core interleaves,
 13	/// clusters, cues and closes the file. **A composition with no audio track is a silent
 14	/// movie**, as in `ExportWriter.addAudio`: no audio output, encoder or queue, and the layout
 15	/// has no audio track.
 16	///
 17	/// **Two pumps.** The video pump is `ExportEncodePump` on `videoQueue` into an
 18	/// `ExportWebMPacketSink`. The audio pump reads, checks the time, applies the gain, cuts at
 19	/// the range (`end.fit`), encodes and adds, on `audioQueue`; once the read is dry it encodes
 20	/// the padding silence and the encoder's tail and cuts the surplus by DiscardPadding
 21	/// (CX-15 (5)). Neither waits on the file: the core queues what the interleave holds. An
 22	/// audio pump that stops early keeps reading, unencoded, until the video pump has left
 23	/// (`drain`): a reader output nobody reads starves the other (G-17).
 24	///
 25	/// **Cancellation, failure and progress** are `ExportWriter`'s: a flag both pumps read, the
 26	/// reader cancelled only after both have left (G-17), progress from the frames submitted.
 27	/// A cancelled or failed export drops the writer and removes the file; a finished one is
 28	/// closed by `ReelWebM.finish()` off the main thread and reported on main.
 29	final class ExportWebMWriter: ExportPipeline, ExportAudioNormalizing {
 30	    private let built: BuiltComposition
 31	    private let destination: URL
 32	    private let range: CMTimeRange
 33	    private let totalSeconds: Double
 34	    private let reader: AVAssetReader
 35	    private let videoOutput: AVAssetReaderOutput
 36	    private var audioOutput: AVAssetReaderOutput?
 37	    private let pump: ExportEncodePump
 38	    private let opus: ExportOpusEncoder?
 39	    private let audioEnd: ExportAudioEnd
 40	    private let layoutJSON: String
 41	    private var webm: ReelWebM?
 42	    /// Written once on main between `init` and `start`, then read only on `audioQueue`.
 43	    private var audioGain: ExportAudioGain?
 44	
 45	    private let videoQueue = DispatchQueue(
 46	        label: "com.kgalligan.framejob.export.webm.video", qos: .userInitiated)
 47	    private let audioQueue = DispatchQueue(
 48	        label: "com.kgalligan.framejob.export.webm.audio", qos: .userInitiated)
 49	
 50	    /// Guards everything the pumps and the main thread both touch.
 51	    private let lock = NSLock()
 52	    private var progressValue: Double = 0
 53	    private var cancelRequested = false
 54	    private var failure: (any Error)?
 55	    /// Set once the video pump has left its group (`drain` reads it).
 56	    private var videoLeft = false
 57	    /// Called once, on the main thread, and then dropped.
 58	    private var completion: ((Result<URL, any Error>) -> Void)?
 59	
 60	    /// Builds the reader's video output, the encoder pump, the Opus encoder when there is
 61	    /// sound and the file's layout, or throws the `Exporter.ExportError` the sheet shows.
 62	    /// Nothing is read or written until `start`.
 63	    init(
 64	        built: BuiltComposition, settings: ExportSettings, chapters: [ExportChapter], to url: URL
 65	    ) throws {
 66	        guard settings.writer == ExportEncodePump.writer else {
 67	            throw Exporter.ExportError.presetUnavailable(ExportWriter.presetName(settings))
 68	        }
 69	        self.built = built
 70	        destination = url
 71	        range = Exporter.timeRange(settings, composition: built.composition)
 72	        totalSeconds = max(0, CMTimeGetSeconds(range.duration))
 73	        audioEnd = ExportAudioEnd(range: range)
 74	        do {
 75	            reader = try AVAssetReader(asset: built.composition)
 76	        } catch {
 77	            throw Exporter.ExportError.failed(error.localizedDescription)
 78	        }
 79	        reader.timeRange = range
 80	        // `ExportWriter.addVideo`'s guard: the placeholder track makes this never empty.
 81	        guard !built.composition.tracks(withMediaType: .video).isEmpty else {
 82	            throw Exporter.ExportError.emptyTimeline
 83	        }
 84	        let canvas = built.videoComposition.renderSize
 85	        videoOutput = ExportWriter.videoReadOutput(built, settings: settings)
 86	        guard reader.canAdd(videoOutput) else {
 87	            throw Exporter.ExportError.failed("The composition could not be read for export.")
 88	        }
 89	        reader.add(videoOutput)
 90	        pump = try ExportEncodePump(settings: settings, canvas: canvas, range: range)
 91	        // The silent movie (CX-15 (2)): no sound, no encoder, no audio track.
 92	        let hasAudio = !built.composition.tracks(withMediaType: .audio).isEmpty
 93	        opus = hasAudio
 94	            ? try ExportOpusEncoder(
 95	                bitRate: settings.audioBitrate.map { max(1, $0) }
 96	                    ?? ExportOpusEncoder.defaultBitRate)
 97	            : nil
 98	        layoutJSON = try ExportWebMLayout(
 99	            settings: settings, range: range, config: pump.config, picture: pump.picture,
100	            preSkip: opus?.preSkip, chapters: chapters
101	        ).json()
102	    }
103	
104	    @available(*, unavailable) required init?(coder: NSCoder) {
105	        fatalError("ExportWebMWriter does not support NSCoder")
106	    }
107	
108	    /// `ExportWriter.normalizeAudio`'s rule: a non-finite, non-positive or unit gain is
109	    /// ignored, so an export that was not normalised reads the 16-bit decode.
110	    func normalizeAudio(byLinearGain gain: Float) {
111	        guard gain.isFinite, gain > 0, gain != 1 else { return }
112	        audioGain = ExportAudioGain(linearGain: gain)
113	    }
114	
115	    // MARK: - Running
116	
117	    /// Starts the write. Main thread; `completion` is called exactly once, on main.
118	    func start(completion: @escaping (Result<URL, any Error>) -> Void) {
119	        self.completion = completion
120	        guard !isStopping else { return report(.failure(Exporter.ExportError.cancelled)) }
121	        if opus != nil {
122	            let output = ExportWriter.audioReadOutput(built, gained: audioGain != nil)
123	            guard reader.canAdd(output) else {
124	                return report(.failure(Exporter.ExportError.failed(
125	                    "The audio mix could not be read for export.")))
126	            }
127	            reader.add(output)
128	            audioOutput = output
129	        }
130	        let webm: ReelWebM
131	        do {
132	            webm = try ReelWebM(path: destination.path, layoutJSON: layoutJSON)
133	        } catch {
134	            return report(.failure(Exporter.ExportError.failed(
135	                "The WebM file could not be made: \(error.localizedDescription)")))
136	        }
137	        self.webm = webm
138	        guard reader.startReading() else {
139	            discard()
140	            return report(.failure(reader.error ?? Exporter.ExportError.failed(
141	                "The composition could not be read for export.")))
142	        }
143	        let group = DispatchGroup()
144	        // The video pump's own group, so the audio pump knows when it has left (`drain`).
145	        let video = DispatchGroup()
146	        group.enter()
147	        pump.run(
148	            sink: ExportWebMPacketSink(webm: webm), output: videoOutput, on: videoQueue,
149	            group: video, isStopping: { [weak self] in self?.isStopping ?? true },
150	            readFailure: { [weak self] in self?.readFailure },
151	            fail: { [weak self] error in self?.stopped(with: error) },
152	            advance: { [weak self] time in self?.advance(to: time) })
153	        video.notify(queue: videoQueue) { [self] in
154	            lock.lock()
155	            videoLeft = true
156	            lock.unlock()
157	            group.leave()
158	        }
159	        if let opus, let output = audioOutput {
160	            group.enter()
161	            audioQueue.async { [self] in
162	                defer { group.leave() }
163	                if !pumpAudio(output, into: webm, through: opus) { drain(output) }
164	            }
165	        }
166	        group.notify(queue: .main) { [weak self] in self?.allPumpsLeft() }
167	    }
168	
169	    /// Sets the flag; both pumps see it before their next sample. Any thread, any time.
170	    func cancel() {
171	        lock.lock()
172	        cancelRequested = true
173	        lock.unlock()
174	    }
175	
176	    var progress: Double {
177	        lock.lock()
178	        defer { lock.unlock() }
179	        return progressValue
180	    }
181	
182	    // MARK: - The audio pump
183	
184	    /// Reads the mix to its end, encodes it and adds each packet at k × 20 ms, holding the
185	    /// newest back so the last one can carry the tail's DiscardPadding (CX-15 (5)). False when
186	    /// it stopped before the read ran dry.
187	    private func pumpAudio(
188	        _ output: AVAssetReaderOutput, into webm: ReelWebM, through opus: ExportOpusEncoder
189	    ) -> Bool {
190	        let gain = audioGain
191	        var held: Data?
192	        var added: Int64 = 0
193	        let add = { (packet: Data, padding: Int64) throws in
194	            try webm.add(
195	                track: ReelWebM.audio, ptsNs: added * 20_000_000, key: true,
196	                discardPaddingNs: padding, data: packet)
197	            added += 1
198	        }
199	        let feed = { (packets: [Data]) throws in
200	            for packet in packets {
201	                if let previous = held { try add(previous, 0) }
202	                held = packet
203	            }
204	        }
205	        var dry = false
206	        do {
207	            while true {
208	                guard !isStopping else { return false }
209	                guard let decoded = output.copyNextSampleBuffer() else {
210	                    dry = true
211	                    if let error = readFailure {
212	                        stopped(with: error)
213	                        return true
214	                    }
215	                    break
216	                }
217	                let time = CMSampleBufferGetPresentationTimeStamp(decoded) - range.start
218	                guard time.isNumeric, time >= .zero else { continue }
219	                if gain != nil, CMSampleBufferGetNumSamples(decoded) == 0 { continue }
220	                guard let sample = gain == nil ? decoded : gain?.apply(to: decoded) else {
221	                    stopped(with: Exporter.ExportError.failed(
222	                        "The loudness gain could not be applied to a sample."))
223	                    return false
224	                }
225	                guard let fitted = audioEnd.fit(sample) else { continue }
226	                try feed(try opus.encode(fitted))
227	            }
228	            for silence in audioEnd.padding() {
229	                try feed(try opus.encode(silence))
230	            }
231	            var tail = (held.map { [$0] } ?? []) + (try opus.finish())
232	            // The decoded length is packets × 960 − pre-skip; the surplus over #337's
233	            // target is cut whole packets first, then by the last one's DiscardPadding.
234	            var padding = (Int(added) + tail.count) * ExportOpusEncoder.framesPerPacket
235	                - opus.preSkip - audioEnd.target
236	            while padding >= ExportOpusEncoder.framesPerPacket, !tail.isEmpty {
237	                tail.removeLast()
238	                padding -= ExportOpusEncoder.framesPerPacket
239	            }
240	            guard padding >= 0, padding < ExportOpusEncoder.framesPerPacket else {
241	                stopped(with: Exporter.ExportError.failed(
242	                    "The audio could not be encoded to its exact length."))
243	                return true
244	            }
245	            let paddingNs = (Int64(padding) * 1_000_000_000 + 24_000) / 48_000
246	            for (index, packet) in tail.enumerated() {
247	                try add(packet, index == tail.count - 1 ? paddingNs : 0)
248	            }
249	            try webm.endTrack(ReelWebM.audio)
250	        } catch {
251	            stopped(with: error)
252	        }
253	        return dry
254	    }
255	
256	    /// Reads and drops the mix until the video pump has left, after the audio pump stopped
257	    /// early: an output nobody reads starves the other (G-17), and the video pump sees the
258	    /// stop only between its reads, so it must be able to finish the one it is in.
259	    private func drain(_ output: AVAssetReaderOutput) {
260	        while true {
261	            lock.lock()
262	            let left = videoLeft
263	            lock.unlock()
264	            guard !left, output.copyNextSampleBuffer() != nil else { return }
265	        }
266	    }
267	
268	    // MARK: - Finishing
269	
270	    private var isStopping: Bool {
271	        lock.lock()
272	        defer { lock.unlock() }
273	        return cancelRequested || failure != nil
274	    }
275	
276	    private func stopped(with error: any Error) {
277	        lock.lock()
278	        if failure == nil { failure = error }
279	        lock.unlock()
280	    }
281	
282	    private var readFailure: (any Error)? {
283	        guard reader.status == .failed else { return nil }
284	        return reader.error
285	            ?? Exporter.ExportError.failed("The composition could not be read to the end.")
286	    }
287	
288	    private func advance(to time: CMTime) {
289	        guard totalSeconds > 0 else { return }
290	        let fraction = CMTimeGetSeconds(time) / totalSeconds
291	        lock.lock()
292	        progressValue = min(max(fraction, progressValue), 1)
293	        lock.unlock()
294	    }
295	
296	    /// Main thread, once both pumps have left: the reader cancelled on a stop (G-17), the
297	    /// encoder closed, then the file finished off main or dropped and removed.
298	    private func allPumpsLeft() {
299	        lock.lock()
300	        let error = failure
301	        let cancelled = cancelRequested
302	        lock.unlock()
303	        if error != nil || cancelled { reader.cancelReading() }
304	        pump.close()
305	        if let error { return finishFailed(error) }
306	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
307	        guard let webm else { return finishFailed(Exporter.ExportError.cancelled) }
308	        videoQueue.async { [weak self] in
309	            let closed: (any Error)?
310	            do {
311	                try webm.finish()
312	                closed = nil
313	            } catch {
314	                closed = Exporter.ExportError.failed(
315	                    "The WebM file could not be finished: \(error.localizedDescription)")
316	            }
317	            DispatchQueue.main.async { self?.fileClosed(closed) }
318	        }
319	    }
320	
321	    private func fileClosed(_ error: (any Error)?) {
322	        lock.lock()
323	        let cancelled = cancelRequested
324	        lock.unlock()
325	        if let error { return finishFailed(error) }
326	        // A cancel while the file was being closed still means "I do not want this file".
327	        if cancelled { return finishFailed(Exporter.ExportError.cancelled) }
328	        lock.lock()
329	        progressValue = 1
330	        lock.unlock()
331	        report(.success(destination))
332	    }
333	
334	    private func finishFailed(_ error: any Error) {
335	        discard()
336	        report(.failure(error))
337	    }
338	
339	    /// Drops the writer and removes the part-written file.
340	    private func discard() {
341	        webm = nil
342	        try? FileManager.default.removeItem(at: destination)
343	    }
344	
345	    /// The one exit, main thread, at most once.
346	    private func report(_ result: Result<URL, any Error>) {
347	        guard let completion else { return }
348	        self.completion = nil
349	        completion(result)
350	    }
351	}

