  1	import AVFoundation
  2	
  3	/// The `av1_webm` row's sound (spec §11 CX-7, CX-15 (5)): the export's 16-bit interleaved
  4	/// 48 kHz stereo mix (`ExportWriter.decodedAudioSettings`, or `ExportAudioGain`'s output in
  5	/// that shape) encoded to Opus by AudioToolbox's `AVAudioConverter`, in 20 ms packets.
  6	///
  7	/// **A 960-frame FIFO** sits in front of the converter, so it is handed whole packets'
  8	/// worth of frames whatever size the reader's buffers come in; packet k is timed at
  9	/// k × 20 ms. **The pre-skip** is the converter's `primeInfo.leadingFrames` (312 measured),
 10	/// which the WebM's OpusHead and CodecDelay carry. **The end:** `finish()` feeds `preSkip`
 11	/// frames of silence through the FIFO (and zeros to a whole packet), then the end of stream,
 12	/// so the packets cover every frame fed — packets × 960 ≥ pre-skip + frames fed — and the
 13	/// writer cuts the surplus with DiscardPadding.
 14	///
 15	/// One instance per export, used only on the WebM writer's audio queue.
 16	final class ExportOpusEncoder {
 17	    /// The AAC rows' own default (spec §11 CX-15 (5)).
 18	    static let defaultBitRate = 192_000
 19	    static let framesPerPacket = 960
 20	    private static let channels = 2
 21	
 22	    let preSkip: Int
 23	    /// Frames handed to the FIFO, silence from `finish` included.
 24	    private(set) var framesFed = 0
 25	    /// Packets the converter has answered.
 26	    private(set) var packetsOut = 0
 27	
 28	    private let converter: AVAudioConverter
 29	    private let inputFormat: AVAudioFormat
 30	    private let outputFormat: AVAudioFormat
 31	    /// Interleaved samples not yet handed to the converter.
 32	    private var fifo: [Int16] = []
 33	    private var finished = false
 34	
 35	    /// A converter at `bitRate` bits per second, snapped to the nearest rate it offers.
 36	    init(bitRate: Int) throws {
 37	        var opus = AudioStreamBasicDescription(
 38	            mSampleRate: 48_000, mFormatID: kAudioFormatOpus, mFormatFlags: 0,
 39	            mBytesPerPacket: 0, mFramesPerPacket: UInt32(Self.framesPerPacket),
 40	            mBytesPerFrame: 0, mChannelsPerFrame: UInt32(Self.channels), mBitsPerChannel: 0,
 41	            mReserved: 0)
 42	        guard let input = AVAudioFormat(
 43	            commonFormat: .pcmFormatInt16, sampleRate: 48_000,
 44	            channels: AVAudioChannelCount(Self.channels), interleaved: true),
 45	            let output = AVAudioFormat(streamDescription: &opus),
 46	            let converter = AVAudioConverter(from: input, to: output)
 47	        else {
 48	            throw Exporter.ExportError.failed("The Opus encoder could not be started.")
 49	        }
 50	        let offered = (converter.applicableEncodeBitRates ?? []).map(\.intValue)
 51	        if let nearest = offered.min(by: { abs($0 - bitRate) < abs($1 - bitRate) }) {
 52	            converter.bitRate = nearest
 53	        } else {
 54	            converter.bitRate = max(1, bitRate)
 55	        }
 56	        self.converter = converter
 57	        inputFormat = input
 58	        outputFormat = output
 59	        preSkip = Int(converter.primeInfo.leadingFrames)
 60	    }
 61	
 62	    @available(*, unavailable) required init?(coder: NSCoder) {
 63	        fatalError("ExportOpusEncoder does not support NSCoder")
 64	    }
 65	
 66	    /// Feeds `sample`'s frames and answers every packet the converter makes of whole
 67	    /// 960-frame chunks. Throws when the buffer is not the 16-bit stereo it should be, or
 68	    /// the converter fails.
 69	    func encode(_ sample: CMSampleBuffer) throws -> [Data] {
 70	        let frames = CMSampleBufferGetNumSamples(sample)
 71	        guard frames > 0 else { return [] }
 72	        guard let block = CMSampleBufferGetDataBuffer(sample),
 73	            CMBlockBufferGetDataLength(block) == frames * Self.channels * 2
 74	        else {
 75	            throw Exporter.ExportError.failed("A sound buffer could not be read for Opus.")
 76	        }
 77	        let start = fifo.count
 78	        fifo.append(contentsOf: repeatElement(0, count: frames * Self.channels))
 79	        let copied = fifo.withUnsafeMutableBytes { bytes -> OSStatus in
 80	            guard let base = bytes.baseAddress else { return -1 }
 81	            return CMBlockBufferCopyDataBytes(
 82	                block, atOffset: 0, dataLength: frames * Self.channels * 2,
 83	                destination: base + start * 2)
 84	        }
 85	        guard copied == kCMBlockBufferNoErr else {
 86	            throw Exporter.ExportError.failed("A sound buffer could not be read for Opus.")
 87	        }
 88	        framesFed += frames
 89	        return try drain()
 90	    }
 91	
 92	    /// The pre-skip's silence, zeros to a whole packet, then the end of stream: every packet
 93	    /// that yields.
 94	    func finish() throws -> [Data] {
 95	        guard !finished else { return [] }
 96	        finished = true
 97	        fifo.append(contentsOf: repeatElement(0, count: preSkip * Self.channels))
 98	        framesFed += preSkip
 99	        let partial = (fifo.count / Self.channels) % Self.framesPerPacket
100	        if partial > 0 {
101	            fifo.append(contentsOf: repeatElement(
102	                0, count: (Self.framesPerPacket - partial) * Self.channels))
103	        }
104	        var packets = try drain()
105	        while true {
106	            let (more, ended) = try convert(nil)
107	            packets += more
108	            if ended || more.isEmpty { break }
109	        }
110	        return packets
111	    }
112	
113	    // MARK: - The converter
114	
115	    /// Hands every whole chunk in the FIFO to the converter.
116	    private func drain() throws -> [Data] {
117	        var packets: [Data] = []
118	        let chunk = Self.framesPerPacket * Self.channels
119	        while fifo.count >= chunk {
120	            guard let buffer = AVAudioPCMBuffer(
121	                pcmFormat: inputFormat, frameCapacity: AVAudioFrameCount(Self.framesPerPacket)),
122	                let samples = buffer.int16ChannelData?[0]
123	            else {
124	                throw Exporter.ExportError.failed("A sound buffer could not be made for Opus.")
125	            }
126	            buffer.frameLength = AVAudioFrameCount(Self.framesPerPacket)
127	            fifo.withUnsafeBufferPointer { from in
128	                guard let base = from.baseAddress else { return }
129	                samples.update(from: base, count: chunk)
130	            }
131	            fifo.removeFirst(chunk)
132	            packets += try convert(buffer).packets
133	        }
134	        return packets
135	    }
136	
137	    /// One call of the converter with `buffer` as its only input (nil: the end of stream),
138	    /// answering the packets it wrote and whether the stream has ended.
139	    private func convert(_ buffer: AVAudioPCMBuffer?) throws -> (packets: [Data], ended: Bool) {
140	        let size = max(converter.maximumOutputPacketSize, 1_500)
141	        let out = AVAudioCompressedBuffer(
142	            format: outputFormat, packetCapacity: 8, maximumPacketSize: size)
143	        var given = false
144	        var error: NSError?
145	        let status = converter.convert(to: out, error: &error) { _, outStatus in
146	            if let buffer, !given {
147	                given = true
148	                outStatus.pointee = .haveData
149	                return buffer
150	            }
151	            outStatus.pointee = buffer == nil ? .endOfStream : .noDataNow
152	            return nil
153	        }
154	        if status == .error {
155	            throw Exporter.ExportError.failed(
156	                "The sound could not be encoded to Opus: "
157	                    + (error?.localizedDescription ?? "the converter gave no reason"))
158	        }
159	        var packets: [Data] = []
160	        if let descriptions = out.packetDescriptions {
161	            for i in 0..<Int(out.packetCount) {
162	                let d = descriptions[i]
163	                packets.append(Data(
164	                    bytes: out.data + Int(d.mStartOffset), count: Int(d.mDataByteSize)))
165	            }
166	        }
167	        packetsOut += packets.count
168	        return (packets, status == .endOfStream)
169	    }
170	}
  1	import AVFoundation
  2	
  3	/// Where `ExportEncodePump`'s AV1 packets go, once the pump has stripped their temporal
  4	/// delimiters and put them in order (spec §11 CX-12, CX-15): the MP4 row's passthrough
  5	/// `AVAssetWriterInput`, or the WebM row's core writer. Both are called on the pump's encode
  6	/// queue alone, so a sink needs no lock of its own.
  7	protocol ExportPacketSink: AnyObject {
  8	    /// Writes one packet presented at `time` for `duration`; `key` is a KEY_FRAME. nil once
  9	    /// written; `ExportPacketSinkStopped` when the export stopped first (nothing to report);
 10	    /// any other error fails the export.
 11	    func append(
 12	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
 13	    ) -> (any Error)?
 14	    /// No packet follows: the pump's one exit calls it exactly once, clean or not.
 15	    func finish()
 16	}
 17	
 18	/// A sink's answer when the export stopped while it waited: the stop is already recorded
 19	/// (a cancel, or another pump's failure), so the pump reports nothing for it.
 20	struct ExportPacketSinkStopped: Error {}
 21	
 22	/// The `av1` row's sink: each packet as one `av01` sample (`ExportAV1Track.sample`) into the
 23	/// passthrough input, after waiting for it to take more; `finish` marks the input finished.
 24	final class ExportMP4PacketSink: ExportPacketSink {
 25	    private let input: AVAssetWriterInput
 26	    private let format: CMVideoFormatDescription
 27	
 28	    init(input: AVAssetWriterInput, format: CMVideoFormatDescription) {
 29	        self.input = input
 30	        self.format = format
 31	    }
 32	
 33	    @available(*, unavailable) required init?(coder: NSCoder) {
 34	        fatalError("ExportMP4PacketSink does not support NSCoder")
 35	    }
 36	
 37	    func append(
 38	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
 39	    ) -> (any Error)? {
 40	        guard let sample = ExportAV1Track.sample(
 41	            data, at: time, duration: duration, format: format)
 42	        else {
 43	            return Exporter.ExportError.failed("An AV1 packet could not be made a sample.")
 44	        }
 45	        while !input.isReadyForMoreMediaData {
 46	            guard !isStopping() else { return ExportPacketSinkStopped() }
 47	            usleep(1000)
 48	        }
 49	        guard input.append(sample) else {
 50	            return Exporter.ExportError.failed("The file could not be written.")
 51	        }
 52	        return nil
 53	    }
 54	
 55	    func finish() {
 56	        input.markAsFinished()
 57	    }
 58	}
 59	
 60	/// The `av1_webm` row's sink: each packet into the core's writer as the video track's block
 61	/// at its time in nanoseconds, the key flag from SVT (spec §11 CX-15 (3)). The core queues
 62	/// what the interleave holds back, so this never waits. `finish` ends the video track; a
 63	/// failure there is the writer's `finish`'s to report.
 64	final class ExportWebMPacketSink: ExportPacketSink {
 65	    private let webm: ReelWebM
 66	
 67	    init(webm: ReelWebM) {
 68	        self.webm = webm
 69	    }
 70	
 71	    @available(*, unavailable) required init?(coder: NSCoder) {
 72	        fatalError("ExportWebMPacketSink does not support NSCoder")
 73	    }
 74	
 75	    func append(
 76	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
 77	    ) -> (any Error)? {
 78	        do {
 79	            try webm.add(
 80	                track: ReelWebM.video, ptsNs: Self.nanoseconds(time), key: key,
 81	                discardPaddingNs: 0, data: data)
 82	        } catch {
 83	            return Exporter.ExportError.failed(
 84	                "The WebM file could not be written: \(error.localizedDescription)")
 85	        }
 86	        return nil
 87	    }
 88	
 89	    func finish() {
 90	        try? webm.endTrack(ReelWebM.video)
 91	    }
 92	
 93	    /// `time` in nanoseconds, rounded half away from zero.
 94	    static func nanoseconds(_ time: CMTime) -> Int64 {
 95	        CMTimeConvertScale(time, timescale: 1_000_000_000, method: .roundHalfAwayFromZero).value
 96	    }
 97	}

