 52	#[derive(Default)]
 53	struct Track {
 54	    queue: VecDeque<Packet>,
 55	    last_ns: Option<i64>,
 56	    ended: bool,
 57	}
 58	
 59	/// The open Cluster: where its size is to be patched, and its time.
 60	struct Cluster {
 61	    size_at: u64,
 62	    ms: u64,
 63	}
 64	
 65	/// One WebM file being written.
 66	pub struct WebmWriter {
 67	    file: Option<BufWriter<File>>,
 68	    pos: u64,
 69	    segment_data: u64,
 70	    level_one: Vec<(u32, u64)>,
 71	    tracks: [Option<Track>; 2],
 72	    cluster: Option<Cluster>,
 73	    cues: Vec<(u64, u64)>,
 74	    failed: bool,
 75	}
 76	
 77	impl WebmWriter {
 78	    /// Checks `layout` (JSON), creates the file at `path` and writes
 79	    /// everything up to the first Cluster.
 80	    pub fn open(path: &Path, layout: &str) -> Result<WebmWriter, String> {
 81	        let head = WebmLayout::header(layout)?;
 82	        let file =
 83	            File::create(path).map_err(|e| format!("the file could not be created ({e})"))?;
 84	        let mut w = WebmWriter {
 85	            file: Some(BufWriter::new(file)),
 86	            pos: 0,
 87	            segment_data: 0,
 88	            level_one: Vec::new(),
 89	            tracks: [
 90	                head.video.then(Track::default),
 91	                head.audio.then(Track::default),
 92	            ],
 93	            cluster: None,
 94	            cues: Vec::new(),
 95	            failed: false,
 96	        };
 97	        w.put(&ebml::ebml_header())?;
 98	        w.put(&ebml::id(ebml::SEGMENT))?;
 99	        w.put(&ebml::UNKNOWN_SIZE)?;
100	        w.segment_data = w.pos;
101	        w.put(&ebml::void(SEEK_RESERVE))?;
102	        let level_one = [
103	            Some((ebml::INFO, head.info)),
104	            Some((ebml::TRACKS, head.tracks)),
105	            head.chapters.map(|bytes| (ebml::CHAPTERS, bytes)),
106	        ];
107	        for (id, bytes) in level_one.into_iter().flatten() {
108	            w.level_one.push((id, w.pos - w.segment_data));
109	            w.put(&bytes)?;
110	        }
111	        w.flush()?;
112	        Ok(w)
113	    }
114	
115	    /// Queues one packet of `track` and writes whatever the interleave
116	    /// allows. `pts_ns` must be at or after 0 and after the track's last.
117	    pub fn add_packet(
118	        &mut self,
119	        track: u32,
120	        pts_ns: i64,
121	        key: bool,
122	        discard_padding_ns: i64,
123	        bytes: &[u8],
124	    ) -> Result<(), String> {
125	        let t = self.track(track)?;
126	        if pts_ns < 0 {
127	            return Err(format!("pts {pts_ns} ns on track {track} is negative"));
128	        }
129	        if let Some(last) = t.last_ns.filter(|last| pts_ns <= *last) {
130	            return Err(format!(
131	                "pts {pts_ns} ns on track {track} is not after its last, {last} ns"
132	            ));
133	        }
134	        t.last_ns = Some(pts_ns);
135	        // round-half-up(pts_ns / 1e6) ms.
136	        let ms = (pts_ns as u64).saturating_add(500_000) / 1_000_000;
137	        t.queue.push_back(Packet {
138	            ms,
139	            key,
140	            discard_ns: discard_padding_ns,
141	            bytes: bytes.to_vec(),
142	        });
143	        self.drain(false)?;
144	        self.flush()
145	    }
146	
147	    /// Ends `track`: no packet follows, and the others no longer wait for it.
148	    pub fn end_track(&mut self, track: u32) -> Result<(), String> {
149	        self.track(track)?.ended = true;
150	        self.drain(false)?;
151	        self.flush()
152	    }
153	
154	    /// Writes every queued packet, the Cues, the SeekHead and the Segment's
155	    /// size, and closes the file. Nothing may be added after it.
156	    pub fn finish(&mut self) -> Result<(), String> {
157	        self.check_open()?;
158	        for t in self.tracks.iter_mut().flatten() {
159	            t.ended = true;
160	        }
161	        self.drain(true)?;
162	        self.close_cluster()?;
163	        let mut seeks = self.level_one.clone();
164	        if !self.cues.is_empty() {
165	            seeks.push((ebml::CUES, self.pos - self.segment_data));
166	            let cues = ebml::cues(&self.cues);
167	            self.put(&cues)?;
168	        }
169	        let mut head = ebml::seek_head(&seeks);
170	        head.extend(ebml::void(SEEK_RESERVE - head.len()));
171	        self.patch(self.segment_data, &head)?;
172	        let size = ebml::size8(self.pos - self.segment_data);
173	        self.patch(self.segment_data - 8, &size)?;
174	        self.flush()?;
175	        self.file = None;
176	        Ok(())
177	    }
178	
179	    // ---- the interleave -----------------------------------------------------
180	
181	    fn check_open(&self) -> Result<(), String> {
182	        if self.file.is_none() {
183	            return Err("the file is finished".to_string());
184	        }
185	        if self.failed {
186	            return Err("the file could not be written earlier".to_string());
187	        }
188	        Ok(())
189	    }
190	
191	    /// The open track `number`, or the sentence refusing it.
192	    fn track(&mut self, number: u32) -> Result<&mut Track, String> {
193	        self.check_open()?;
194	        let slot = match number {
195	            VIDEO => self.tracks[0].as_mut(),
196	            AUDIO => self.tracks[1].as_mut(),
197	            _ => None,
198	        };
199	        let t = slot.ok_or_else(|| format!("track {number} is not in the layout"))?;
200	        if t.ended {
201	            return Err(format!("track {number} has ended"));
202	        }
203	        Ok(t)
204	    }
205	
206	    /// Writes heads while the interleave allows; `all` writes every one.
207	    fn drain(&mut self, all: bool) -> Result<(), String> {
208	        loop {
209	            let waiting = self
210	                .tracks
211	                .iter()
212	                .flatten()
213	                .any(|t| !t.ended && t.queue.is_empty());
214	            if waiting && !all {
215	                return Ok(());
216	            }
217	            let next = (0..2)
218	                .filter_map(|i| {
219	                    let head = self.tracks[i].as_ref()?.queue.front()?;
220	                    Some((head.ms, i))
221	                })
222	                .min();
223	            let Some((_, i)) = next else {
224	                return Ok(());
225	            };
226	            let Some(packet) = self.tracks[i].as_mut().and_then(|t| t.queue.pop_front()) else {
227	                return Ok(());
228	            };
229	            self.write_block(i as u32 + 1, &packet)?;
230	        }
231	    }
232	
233	    fn write_block(&mut self, track: u32, p: &Packet) -> Result<(), String> {
234	        let video_key = track == VIDEO && p.key;
235	        let fresh = match &self.cluster {
236	            None => true,
237	            Some(c) => video_key || p.ms.saturating_sub(c.ms) > MAX_RELATIVE_MS,
238	        };
239	        if fresh {
240	            self.close_cluster()?;
241	            if video_key {
242	                self.cues.push((p.ms, self.pos - self.segment_data));
243	            }
244	            self.put(&ebml::id(ebml::CLUSTER))?;
245	            let size_at = self.pos;
246	            self.put(&ebml::UNKNOWN_SIZE)?;
247	            self.put(&ebml::uint(ebml::TIMESTAMP, p.ms))?;
248	            self.cluster = Some(Cluster { size_at, ms: p.ms });
249	        }
250	        let base = self.cluster.as_ref().map_or(p.ms, |c| c.ms);
251	        let relative = i16::try_from(p.ms.saturating_sub(base)).unwrap_or(i16::MAX);
252	        let element = if p.discard_ns > 0 {
253	            ebml::block_group(
254	                &ebml::block_body(track, relative, 0, &p.bytes),
255	                p.discard_ns,
256	            )
257	        } else {
258	            let flags = if track == AUDIO || p.key { 0x80 } else { 0 };
259	            ebml::binary(
260	                ebml::SIMPLE_BLOCK,
261	                &ebml::block_body(track, relative, flags, &p.bytes),
262	            )
263	        };
264	        self.put(&element)
265	    }
266	
267	    fn close_cluster(&mut self) -> Result<(), String> {
268	        if let Some(c) = self.cluster.take() {
269	            let size = ebml::size8(self.pos - c.size_at - 8);
270	            self.patch(c.size_at, &size)?;
271	        }
272	        Ok(())
273	    }
274	
275	    // ---- the file -----------------------------------------------------------
276	
277	    fn io<T>(&mut self, result: std::io::Result<T>) -> Result<T, String> {
278	        result.map_err(|e| {
279	            self.failed = true;
280	            format!("the file could not be written ({e})")
281	        })
282	    }
283	
284	    fn put(&mut self, bytes: &[u8]) -> Result<(), String> {
285	        let Some(file) = self.file.as_mut() else {
286	            return Err("the file is finished".to_string());
287	        };
288	        let written = file.write_all(bytes);
289	        self.io(written)?;
290	        self.pos += bytes.len() as u64;
291	        Ok(())
292	    }
293	
294	    /// Overwrites `bytes` at `at`, then returns to the end.
295	    fn patch(&mut self, at: u64, bytes: &[u8]) -> Result<(), String> {
296	        let end = self.pos;
297	        let Some(file) = self.file.as_mut() else {
298	            return Err("the file is finished".to_string());
299	        };
300	        let done = file
301	            .seek(SeekFrom::Start(at))
302	            .and_then(|_| file.write_all(bytes))
303	            .and_then(|_| file.seek(SeekFrom::Start(end)));
304	        self.io(done).map(|_| ())
305	    }
306	
307	    fn flush(&mut self) -> Result<(), String> {
308	        let Some(file) = self.file.as_mut() else {
309	            return Ok(());
310	        };
311	        let flushed = file.flush();
312	        self.io(flushed)
313	    }
314	}
  1	//! C FFI: the WebM writer (spec §11 CX-6, CX-15) — five `rc_webm_*`
  2	//! exports over `webm_writer.rs`'s `WebmWriter`, each a thin shim through
  3	//! `ffi_util.rs`'s helpers. An `RcWebm` holds the writer behind a mutex, so
  4	//! the app's video and audio queues may add packets, end tracks and finish
  5	//! from several threads at once; each call is whole before the next starts.
  6	
  7	use std::ffi::c_char;
  8	use std::path::Path;
  9	use std::ptr;
 10	use std::slice;
 11	use std::sync::{Mutex, MutexGuard};
 12	
 13	use crate::ffi_util::{boxed, fallible_op, free_boxed, read_cstr};
 14	use crate::webm_writer::WebmWriter;
 15	
 16	/// The handle `rc_webm_open` answers: one file being written.
 17	pub struct RcWebm(Mutex<WebmWriter>);
 18	
 19	/// The writer behind `webm`, locked, or the sentence refusing the call.
 20	///
 21	/// # Safety
 22	/// `webm` must be NULL or a live handle from [`rc_webm_open`].
 23	unsafe fn locked<'a>(webm: *const RcWebm) -> Result<MutexGuard<'a, WebmWriter>, String> {
 24	    if webm.is_null() {
 25	        return Err("webm is NULL".to_string());
 26	    }
 27	    unsafe { &*webm }
 28	        .0
 29	        .lock()
 30	        .map_err(|_| "the writer stopped after an internal error".to_string())
 31	}
 32	
 33	/// Creates the file at `path` and writes its header from `layout_json` (the
 34	/// header's keys). NULL with a lowercase sentence through `err_out` naming
 35	/// the value when the layout is refused or the file cannot be created.
 36	///
 37	/// # Safety
 38	/// `path` and `layout_json` must be NULL or valid NUL-terminated C strings;
 39	/// `err_out` must be NULL or a valid pointer to writable `*mut c_char`,
 40	/// freed with `rc_string_free`. The handle is freed with [`rc_webm_free`].
 41	#[no_mangle]
 42	pub unsafe extern "C" fn rc_webm_open(
 43	    path: *const c_char,
 44	    layout_json: *const c_char,
 45	    err_out: *mut *mut c_char,
 46	) -> *mut RcWebm {
 47	    let body = || {
 48	        let path = unsafe { read_cstr(path, "path") }?;
 49	        let layout = unsafe { read_cstr(layout_json, "layout_json") }?;
 50	        WebmWriter::open(Path::new(&path), &layout).map(|w| RcWebm(Mutex::new(w)))
 51	    };
 52	    unsafe { fallible_op(err_out, "opening a webm file", ptr::null_mut(), body, boxed) }
 53	}
 54	
 55	/// Adds one packet of `track` (`RC_WEBM_VIDEO` or `RC_WEBM_AUDIO`) at
 56	/// `pts_ns`, writing what the interleave allows. False with the sentence
 57	/// through `err_out` for NULL, an unknown or ended track, a negative pts or
 58	/// one not after the track's last, a call after finish, or an I/O failure.
 59	///
 60	/// # Safety
 61	/// `webm` must be NULL or a live handle; `bytes` must be NULL or point to
 62	/// `len` readable bytes; `err_out` as [`rc_webm_open`]'s.
 63	#[no_mangle]
 64	pub unsafe extern "C" fn rc_webm_add_packet(
 65	    webm: *mut RcWebm,
 66	    track: u32,
 67	    pts_ns: i64,
 68	    key: bool,
 69	    discard_padding_ns: i64,
 70	    bytes: *const u8,
 71	    len: usize,
 72	    err_out: *mut *mut c_char,
 73	) -> bool {
 74	    let body = || {
 75	        let mut writer = unsafe { locked(webm) }?;
 76	        if bytes.is_null() {
 77	            return Err("bytes is NULL".to_string());
 78	        }
 79	        let data = unsafe { slice::from_raw_parts(bytes, len) };
 80	        writer.add_packet(track, pts_ns, key, discard_padding_ns, data)
 81	    };
 82	    unsafe { fallible_op(err_out, "adding a webm packet", false, body, |()| true) }
 83	}
 84	
 85	/// Ends `track`: no packet of it follows. False with the sentence through
 86	/// `err_out` for NULL, an unknown or ended track, or a call after finish.
 87	///
 88	/// # Safety
 89	/// `webm` must be NULL or a live handle; `err_out` as [`rc_webm_open`]'s.
 90	#[no_mangle]
 91	pub unsafe extern "C" fn rc_webm_end_track(
 92	    webm: *mut RcWebm,
 93	    track: u32,
 94	    err_out: *mut *mut c_char,
 95	) -> bool {
 96	    let body = || unsafe { locked(webm) }?.end_track(track);
 97	    unsafe { fallible_op(err_out, "ending a webm track", false, body, |()| true) }
 98	}
 99	
100	/// Writes every queued packet, the Cues, the SeekHead and the Segment's size,
101	/// and closes the file. False with the sentence through `err_out` for NULL,
102	/// a second finish, or an I/O failure.
103	///
104	/// # Safety
105	/// `webm` must be NULL or a live handle; `err_out` as [`rc_webm_open`]'s.
106	#[no_mangle]
107	pub unsafe extern "C" fn rc_webm_finish(webm: *mut RcWebm, err_out: *mut *mut c_char) -> bool {
108	    let body = || unsafe { locked(webm) }?.finish();
109	    unsafe { fallible_op(err_out, "finishing a webm file", false, body, |()| true) }
110	}
111	
112	/// Releases a writer. NULL-tolerant. A file not finished is left as it is,
113	/// for the app to remove.
114	///
115	/// # Safety
116	/// `webm` must be NULL or a live handle not already freed.
117	#[no_mangle]
118	pub unsafe extern "C" fn rc_webm_free(webm: *mut RcWebm) {
119	    unsafe { free_boxed(webm, "freeing a webm writer") }
120	}

