     1	import AVFoundation
     2	
     3	/// `rc_webm_open`'s layout (spec §11 CX-15 (3)), the `Encodable` mirror of the core's
     4	/// `WebmLayout`: what the `av1_webm` file is before its first packet. Built from the
     5	/// settings (the size `ExportWriter.encodedSize` gives the encoder, the rate), the pump's
     6	/// `av1C` record and sequence-header colour, its picture (HD-5's HDR10 blobs on PQ alone),
     7	/// the Opus pre-skip when the composition has sound, and the chapters clamped and rebased
     8	/// by `ExportChapter.partition` — the MP4 writer's own rule.
     9	struct ExportWebMLayout: Encodable {
    10	    struct Video: Encodable {
    11	        let codecId = "V_AV1"
    12	        let codecPrivateHex: String
    13	        let width: Int
    14	        let height: Int
    15	        let fps: [Int]
    16	        let colour: Colour
    17	    }
    18	
    19	    /// The sequence header's CICP, video range (Matroska's Range 1), 10 bits, and on PQ the
    20	    /// two blobs `OutputTransform` writes everywhere else.
    21	    struct Colour: Encodable {
    22	        let matrix: Int
    23	        let range = 1
    24	        let transfer: Int
    25	        let primaries: Int
    26	        let bitsPerChannel = 10
    27	        let mdcvHex: String?
    28	        let clliHex: String?
    29	    }
    30	
    31	    struct Audio: Encodable {
    32	        let codecId = "A_OPUS"
    33	        let channels = 2
    34	        let sampleRate = 48_000
    35	        let preSkip: Int
    36	    }
    37	
    38	    struct Chapter: Encodable {
    39	        let startNs: Int64
    40	        let endNs: Int64
    41	        let name: String
    42	    }
    43	
    44	    let durationNs: Int64
    45	    let video: Video
    46	    /// nil for a composition with no sound: the silent movie (CX-15 (2)).
    47	    let audio: Audio?
    48	    let chapters: [Chapter]
    49	
    50	    init(
    51	        settings: ExportSettings, range: CMTimeRange, config: ReelAV1.Config,
    52	        picture: ExportAV1Picture, preSkip: Int?, chapters: [ExportChapter]
    53	    ) {
    54	        let frame = ExportWriter.encodedSize(settings)
    55	        let hdr10 = picture.carriesHDR10
    56	        durationNs = ExportWebMPacketSink.nanoseconds(range.duration)
    57	        video = Video(
    58	            codecPrivateHex: Self.hex(config.record), width: frame.width, height: frame.height,
    59	            fps: [settings.fps.num, settings.fps.den],
    60	            colour: Colour(
    61	                matrix: config.color.matrix, transfer: config.color.transfer,
    62	                primaries: config.color.primaries,
    63	                mdcvHex: hdr10 ? Self.hex(OutputTransform.masteringDisplay) : nil,
    64	                clliHex: hdr10 ? Self.hex(OutputTransform.contentLightLevel) : nil))
    65	        audio = preSkip.map { Audio(preSkip: $0) }
    66	        self.chapters = ExportChapter.partition(chapters, in: range).map {
    67	            Chapter(
    68	                startNs: ExportWebMPacketSink.nanoseconds($0.range.start),
    69	                endNs: ExportWebMPacketSink.nanoseconds($0.range.end), name: $0.name)
    70	        }
    71	    }
    72	
    73	    /// The layout as the core reads it: snake_case keys, an absent optional left out.
    74	    func json() throws -> String {
    75	        let encoder = JSONEncoder()
    76	        encoder.keyEncodingStrategy = .convertToSnakeCase
    77	        guard let text = String(data: try encoder.encode(self), encoding: .utf8) else {
    78	            throw Exporter.ExportError.failed("The WebM layout could not be written.")
    79	        }
    80	        return text
    81	    }
    82	
    83	    private static func hex(_ data: Data) -> String {
    84	        data.map { String(format: "%02x", $0) }.joined()
    85	    }
    86	}
